const logs = items.map((i) => i.json);

if (logs.length === 0) {
  return [{ json: { report: "No emails processed in the last 7 days." } }];
}

// --- Initialize all counters and the new stats structure ---
let totalProcessed = 0;
let errorCount = 0;
let totalAnalyzedItems = 0;
let actionableLogsCount = 0;
const junkedSubjects = [];

const priorityStats = {
  high: { total: 0, modelCounts: {} },
  normal: { total: 0, modelCounts: {} },
  junk: 0,
};

// --- Process all logs in a single, efficient loop ---
for (const log of logs) {
  const priority = log.triage_priority;
  totalProcessed++;

  if (log.has_error) {
    errorCount++;
    if (priority === "junk") {
      priorityStats.junk++;
    }
    continue; // Skip further processing for logs with errors
  }

  const model = log.analysis_model;

  // Tally totals and model counts based on priority
  if (priority === "high") {
    priorityStats.high.total++;
    if (model) {
      priorityStats.high.modelCounts[model] =
        (priorityStats.high.modelCounts[model] || 0) + 1;
    }
  } else if (priority === "normal") {
    priorityStats.normal.total++;
    if (model) {
      priorityStats.normal.modelCounts[model] =
        (priorityStats.normal.modelCounts[model] || 0) + 1;
    }
  } else if (priority === "junk") {
    priorityStats.junk++;
    // Collect subjects of junked emails for review
    if (junkedSubjects.length < 15) {
      junkedSubjects.push(log.email_subject);
    }
  }

  // Concurrently calculate stats for the actionable rate
  if (priority !== "junk") {
    totalAnalyzedItems++;
    if ((log.actionable_item_count || 0) > 0) {
      actionableLogsCount++;
    }
  }
}

const actionableRate =
  totalAnalyzedItems > 0 ? (actionableLogsCount / totalAnalyzedItems) * 100 : 0;

// --- Assemble the final Stats Object with the new structure ---
const stats = {
  totalProcessed,
  totalAnalyzed: totalAnalyzedItems,
  errorCount,
  priorityCounts: priorityStats, // This now contains the new nested structure
  actionableRate: actionableRate.toFixed(1),
  junkedSubjects,
};

return [{ json: { stats } }];

// A simple, robust function to escape text for Telegram's HTML parse mode
function escHTML(text) {
  if (typeof text !== "string" || text.length === 0) return "";
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

const item = items[0];

// Handle case where there were no logs
if (item.json.report) {
  item.json.telegramMessage = item.json.report;
  return item;
}

const stats = item.json.stats || item.stats;

if (!stats) {
  throw new Error("Could not find 'stats' object in the input data.");
}

// Get priority totals from the nested structure
const highPriorityTotal = stats.priorityCounts?.high?.total || 0;
const normalPriorityTotal = stats.priorityCounts?.normal?.total || 0;
const junkTotal = stats.priorityCounts?.junk || 0;

// Get the model count objects
const highModelCounts = stats.priorityCounts?.high?.modelCounts || {};
const normalModelCounts = stats.priorityCounts?.normal?.modelCounts || {};

// Get the junk mail list
let junkListText = "<i>None</i>";
if (stats.junkedSubjects && stats.junkedSubjects.length > 0) {
  junkListText = stats.junkedSubjects.map((s) => `• ${escHTML(s)}`).join("\n");
}

// --- Build the final message directly ---
// This version constructs the model lists inside the template string
// to work around the n8n Code node's string interpolation issue.
let message = `<b>Weekly Automation Review</b> 📊
  (Last 7 Days)

  <b>Processing Summary</b>
  • Total Processed: <b>${stats.totalProcessed}</b>
  • Errors Encountered: <b>${stats.errorCount}</b>

  <b>Triage Breakdown</b>
  • High Priority: <b>${highPriorityTotal}</b>
  • Normal Priority: <b>${normalPriorityTotal}</b>
  • Junk: <b>${junkTotal}</b>

  <b>Cost Analysis (Analysis Calls)</b>
  <u>Expensive (High Priority)</u>
  ${
    Object.keys(highModelCounts).length > 0
      ? Object.keys(highModelCounts)
          .map(
            (modelName) => `• ${escHTML(modelName)}: <b> ${highModelCounts[modelName]}</b>`
          )
          .join("\n  ")
      : "<i>None</i>"
  }

  <u>Cheap (Normal Priority)</u>
  ${
    Object.keys(normalModelCounts).length > 0
      ? Object.keys(normalModelCounts)
          .map(
            (modelName) => `• ${escHTML(modelName)}: <b> ${normalModelCounts[modelName]}</b>`
          )
          .join("\n  ")
      : "<i>None</i>"
  }

  <b>Effectiveness</b>
  • Actionable Rate: <b>${stats.actionableRate}%</b>
  <i>(% of non-junk items that had at least one suggested action)</i>

  <b>Junk Mail for Review (Top 15)</b>
  ${junkListText}`;

// Add Support Footer
message += `\n\n<a href="https://www.buymeacoffee.com/fabcarvalho">Support this project ☕</a>`;

// Ensure item.json exists before assigning
if (!item.json) {
  item.json = {};
}
item.json.telegramMessage = message;

return item;
